const A=require('../server-data/accounts.cjs');module.exports=async(req,res)=>{try{A.guard(req,res);const who=await A.requireUser(req,res);if(who.profile.role!=='admin')return res.status(403).json({error:'Sólo un administrador puede gestionar usuarios.'});if(req.method==='GET'){const users=await A.api('/rest/v1/maq_profiles?select=id,email,full_name,role,created_at&order=created_at.desc&limit=500');return res.status(200).json({users})}if(req.method!=='POST')return res.status(405).json({error:'Método no permitido.'});const b=typeof req.body==='string'?JSON.parse(req.body):req.body||{};const email=String(b.email||'').trim().toLowerCase(),password=String(b.password||'');if(!/^\S+@\S+\.\S+$/.test(email)||email.length>254||password.length<8||password.length>128)return res.status(400).json({error:'Ingresá un correo válido y una contraseña de entre 8 y 128 caracteres.'});const created=await A.api('/auth/v1/admin/users',{method:'POST',body:{email,password,email_confirm:true,user_metadata:{full_name:String(b.name||'').trim().slice(0,100)}}});return res.status(201).json({created:true,id:created.id})}catch(e){return A.error(res,e)}};
